54	fn key_from_keycode(keycode: i64) -> Option<SystemKey> {
55	    match keycode as u16 {
56	        KeyCode::FUNCTION => Some(SystemKey::Fn),
57	        KeyCode::CONTROL => Some(SystemKey::LeftControl),
58	        KeyCode::RIGHT_CONTROL => Some(SystemKey::RightControl),
59	        KeyCode::OPTION => Some(SystemKey::LeftOption),
60	        KeyCode::RIGHT_OPTION => Some(SystemKey::RightOption),
61	        KeyCode::COMMAND => Some(SystemKey::LeftCommand),
62	        KeyCode::RIGHT_COMMAND => Some(SystemKey::RightCommand),
63	        _ => None,
64	    }
65	}
66	
67	fn key_is_down_in_flags(key: SystemKey, flags: CGEventFlags) -> bool {
68	    match key {
69	        SystemKey::Fn => flags.contains(CGEventFlags::CGEventFlagSecondaryFn),
70	        SystemKey::LeftControl | SystemKey::RightControl => {
71	            flags.contains(CGEventFlags::CGEventFlagControl)
72	        }
73	        SystemKey::LeftOption | SystemKey::RightOption => {
74	            flags.contains(CGEventFlags::CGEventFlagAlternate)
75	        }
76	        SystemKey::LeftCommand | SystemKey::RightCommand => {
77	            flags.contains(CGEventFlags::CGEventFlagCommand)
78	        }
79	    }
80	}
81	
82	fn emit_system_key_event(event: &CGEvent) {
83	    let Some(app_handle) = APP_HANDLE.get() else {
84	        return;
85	    };
86	
87	    let keycode = event.get_integer_value_field(EventField::KEYBOARD_EVENT_KEYCODE);
88	    let Some(key) = key_from_keycode(keycode) else {
89	        return;
90	    };
91	
92	    let flags = event.get_flags();
93	    let is_down = key_is_down_in_flags(key, flags);
94	    let mut pressed = pressed_keys()
95	        .lock()
96	        .expect("system key pressed state mutex poisoned");
97	
98	    if is_down {
99	        let was_new_key = pressed.insert(key);
100	
101	        if was_new_key {
102	            let _ = app_handle.emit(
103	                "system-key-pressed",
104	                SystemKeyPressedPayload {
105	                    key,
106	                    pressed_keys: pressed.iter().copied().collect(),
107	                },
108	            );
109	        }
110	
111	        return;
112	    }
113	
114	    if pressed.remove(&key) {
115	        let pressed_keys = pressed.iter().copied().collect::<Vec<_>>();
116	        let _ = app_handle.emit(
117	            "system-key-released",
118	            SystemKeyReleasedPayload { key, pressed_keys },
119	        );
120	
121	        if pressed.is_empty() {
122	            let _ = app_handle.emit("system-keys-released", ());
123	        }
124	    }
125	}
126	
127	fn emit_keyboard_key_pressed(event: &CGEvent) {
128	    let Some(app_handle) = APP_HANDLE.get() else {
129	        return;
130	    };
131	
132	    let is_repeat = event.get_integer_value_field(EventField::KEYBOARD_EVENT_AUTOREPEAT) != 0;
133	    if is_repeat {
134	        return;
135	    }
136	
137	    let key_code = event.get_integer_value_field(EventField::KEYBOARD_EVENT_KEYCODE);
138	    let _ = app_handle.emit(
139	        "keyboard-key-pressed",
140	        KeyboardKeyPressedPayload { key_code },
141	    );
142	}
