144	pub fn setup(app_handle: &tauri::AppHandle) {
145	    APP_HANDLE.set(app_handle.clone()).ok();
146	
147	    if WATCHER_RUNNING.swap(true, Ordering::SeqCst) {
148	        return;
149	    }
150	
151	    thread::spawn(|| {
152	        let tap = CGEventTap::new(
153	            CGEventTapLocation::HID,
154	            CGEventTapPlacement::HeadInsertEventTap,
155	            CGEventTapOptions::ListenOnly,
156	            vec![CGEventType::FlagsChanged, CGEventType::KeyDown],
157	            |_proxy: CGEventTapProxy, event_type: CGEventType, event: &CGEvent| {
158	                match event_type {
159	                    CGEventType::FlagsChanged => emit_system_key_event(event),
160	                    CGEventType::KeyDown => emit_keyboard_key_pressed(event),
161	                    _ => {}
162	                }
163	                None
164	            },
165	        );
166	
167	        let Ok(tap) = tap else {
168	            WATCHER_RUNNING.store(false, Ordering::SeqCst);
169	            return;
170	        };
171	
172	        unsafe {
173	            let source = tap
174	                .mach_port
175	                .create_runloop_source(0)
176	                .expect("failed to create system key run loop source");
177	
178	            let run_loop = CFRunLoop::get_current();
179	            run_loop.add_source(&source, kCFRunLoopCommonModes);
180	            tap.enable();
181	            CFRunLoop::run_current();
182	        }
183	
184	        WATCHER_RUNNING.store(false, Ordering::SeqCst);
185	    });
186	}
