30	
31	    unsafe {
32	        let center = CFNotificationCenterGetDistributedCenter();
33	        let name = CFString::new("com.apple.accessibility.api");
34	        CFNotificationCenterAddObserver(
35	            center,
36	            std::ptr::null(),
37	            on_accessibility_changed,
38	            name.as_concrete_TypeRef(),
39	            std::ptr::null(),
40	            CFNotificationSuspensionBehaviorDeliverImmediately,
41	        );
42	        // The observer retains the name, but we must keep it alive
43	        std::mem::forget(name);
44	    }
45	}
