24	fn install_panic_hook() {
25	    let default_hook = std::panic::take_hook();
26	    std::panic::set_hook(Box::new(move |panic_info| {
27	        let payload = panic_info
28	            .payload()
29	            .downcast_ref::<&str>()
30	            .map(|value| (*value).to_string())
31	            .or_else(|| panic_info.payload().downcast_ref::<String>().cloned())
32	            .unwrap_or_else(|| "unknown panic payload".to_string());
33	
34	        let location = panic_info
35	            .location()
36	            .map(|location| {
37	                format!(
38	                    "{}:{}:{}",
39	                    location.file(),
40	                    location.line(),
41	                    location.column()
42	                )
43	            })
44	            .unwrap_or_else(|| "unknown".to_string());
45	
46	        log::error!(target: "runtime", "rust_panic payload={payload:?} location={location}");
47	
48	        default_hook(panic_info);
49	    }));
50	}
