123		MetaRight: "RightCommand",
124	};
125	
126	let registeredDictationHotkey: RegisteredHotkey | null = null;
127	let registeredDictationHotkeys: RegisteredHotkey[] = [];
128	
129	/**
130	 * Check if a KeyboardEvent.code is a modifier key.
131	 */
132	export function isModifierCode(code: string): boolean {
133		return MODIFIER_CODES.has(code);
134	}
135	
136	/**
137	 * Get the display string for a modifier KeyboardEvent.code during recording.
138	 * Returns undefined for non-modifier codes.
139	 */
140	export function modifierCodeToDisplay(code: string): string | undefined {
141		return CODE_TO_DISPLAY[code];
142	}
143	
144	/**
145	 * Convert a KeyboardEvent.code modifier into the system-only hotkey string
146	 * persisted in settings, when the native watcher supports it.
147	 */
148	export function modifierCodeToSystemHotkey(code: string): string | undefined {
149		return MODIFIER_CODE_TO_SYSTEM_HOTKEY[code];
150	}
151	
152	export function systemHotkeyFromKeys(keys: Iterable<SystemKey>): string {
153		const keySet = new Set(keys);
154	
155		return SYSTEM_HOTKEY_ORDER.filter((part) => {
156			const key = SYSTEM_HOTKEY_TO_KEY[part];
157			return key !== undefined && keySet.has(key);
158		}).join("+");
159	}
160	
161	function systemKeysFromHotkey(hotkey: string): SystemKey[] | undefined {
162		const parts = hotkey.split("+");
163		if (parts.length === 0) return undefined;
164	
165		const keys: SystemKey[] = [];
166		for (const part of parts) {
167			const key = SYSTEM_HOTKEY_TO_KEY[part];
168			if (!key) return undefined;
169			keys.push(key);
170		}
171	
172		return keys;
173	}
174	
175	function systemKeySetsMatch(a: Iterable<SystemKey>, b: Iterable<SystemKey>): boolean {
176		const aSet = new Set(a);
177		const bSet = new Set(b);
178		if (aSet.size !== bSet.size) return false;
179	
180		for (const key of aSet) {
181			if (!bSet.has(key)) return false;
182		}
183	
184		return true;
185	}
186	
187	/**
188	 * Check if a hotkey should be handled by the native system key watcher.
189	 */
190	export function isSystemOnlyHotkey(hotkey: string): boolean {
191		return systemKeysFromHotkey(hotkey) !== undefined;
192	}
193	
194	/**
195	 * Check if a hotkey string can be registered by one of the supported backends.
196	 */
197	export function isValidHotkey(hotkey: string): boolean {
198		if (isSystemOnlyHotkey(hotkey)) return true;
199	
200		const parts = hotkey
201			.split("+")
202			.map((part) => part.trim())
203			.filter(Boolean);
204		if (parts.length < 2) return false;
205		if (parts.some((part) => part in SYSTEM_HOTKEY_TO_KEY)) return false;
206	
207		const key = parts[parts.length - 1];
208		if (!key || COMBO_MODIFIER_NAMES.has(key)) return false;
209	
210		return parts.slice(0, -1).every((part) => COMBO_MODIFIER_NAMES.has(part));
211	}
212	
213	async function registerSystemHotkey(
214		hotkey: string,
215		handlers: HotkeyHandlers
216	): Promise<RegisteredHotkey> {
217		const expectedKeys = systemKeysFromHotkey(hotkey);
218		if (!expectedKeys) {
219			throw new Error(`Unsupported system hotkey: ${hotkey}`);
220		}
221	
222		const watcherStarted = await startSystemKeyWatcher();
223		if (Result.isError(watcherStarted)) {
224			throw watcherStarted.error;
225		}
226	
227		let isHeld = false;
228		let isRecorderActive = false;
229	
230		const unlistenRecorderActive = await listen<HotkeyRecorderActivePayload>(
231			"hotkey-recorder-active",
232			(event) => {
233				isRecorderActive = event.payload.active;
234			}
235		);
236	
237		const unlistenPressed = await listen<SystemKeyPressedPayload>("system-key-pressed", (event) => {
238			if (!systemKeySetsMatch(event.payload.pressedKeys, expectedKeys)) return;
239			if (isHeld) return;
240			if (isRecorderActive) return;
241	
242			isHeld = true;
243			handlers.onPressed();
244		});
245	
246		const unlistenReleased = await listen("system-keys-released", () => {
247			if (isHeld) handlers.onReleased?.();
248			isHeld = false;
249		});
250	
251		const unlistenKeyReleased = await listen<SystemKeyReleasedPayload>(
252			"system-key-released",
253			(event) => {
254				if (systemKeySetsMatch(event.payload.pressedKeys, expectedKeys)) return;
255				if (isHeld) handlers.onReleased?.();
256				isHeld = false;
257			}
258		);
259	
260		return {
261			hotkey,
262			dispose: async () => {
263				unlistenRecorderActive();
264				unlistenPressed();
265				unlistenKeyReleased();
266				unlistenReleased();
267			},
268		};
269	}
270	
271	async function registerGlobalHotkey(
272		hotkey: string,
273		handlers: HotkeyHandlers
274	): Promise<RegisteredHotkey> {
275		await Result.tryPromise(() => unregister(hotkey));
276	
277		await register(hotkey, (event: GlobalShortcutEvent) => {
278			if (event.state === "Pressed") {
279				handlers.onPressed();
280			} else if (event.state === "Released") {
281				handlers.onReleased?.();
282			}
283		});
284	
285		return {
286			hotkey,
287			dispose: async () => {
288				await Result.tryPromise(() => unregister(hotkey));
289			},
290		};
291	}
292	
293	/**
294	 * Register the dictation hotkey using the best backend for the configured hotkey.
295	 * Combo hotkeys use Tauri global-shortcut; supported system-only hotkeys use
296	 * the native macOS system key watcher.
297	 */
298	export async function registerDictationHotkey(
299		hotkey: string,
300		handler: HotkeyHandler
301	): Promise<void> {
302		await unregisterDictationHotkey();
303	
304		registeredDictationHotkey = isSystemOnlyHotkey(hotkey)
305			? await registerSystemHotkey(hotkey, { onPressed: handler })
306			: await registerGlobalHotkey(hotkey, { onPressed: handler });
307	}
308	
309	export async function registerDictationHotkeys(
310		hotkeys: { hotkey: string; onPressed: HotkeyHandler; onReleased?: HotkeyHandler }[]
311	): Promise<void> {
312		await unregisterDictationHotkey();
313	
314		const registered: RegisteredHotkey[] = [];
315		const result = await Result.tryPromise(async () => {
316			for (const config of hotkeys) {
317				registered.push(
318					isSystemOnlyHotkey(config.hotkey)
319						? await registerSystemHotkey(config.hotkey, config)
320						: await registerGlobalHotkey(config.hotkey, config)
321				);
322			}
323		});
324		if (Result.isError(result)) {
325			for (const registration of registered) {
326				await registration.dispose();
327			}
328			throw result.error;
329		}
330		registeredDictationHotkeys = registered;
331	}
332	
333	/**
334	 * Unregister the currently active dictation hotkey, regardless of backend.
335	 */
336	export async function unregisterDictationHotkey(): Promise<void> {
337		const registered = registeredDictationHotkey;
338		const registeredMany = registeredDictationHotkeys;
339		if (!registered && registeredMany.length === 0) return;
340	
341		registeredDictationHotkey = null;
342		registeredDictationHotkeys = [];
343		if (registered) await registered.dispose();
344		for (const registration of registeredMany) {
345			await registration.dispose();
346		}
347	}
348	
349	/**
350	 * Get a user-friendly display name for a hotkey string.
351	 * Handles combo shortcuts like "Command+;" by mapping modifier names to symbols.
352	 */
353	export function hotkeyDisplayName(hotkey: string): string {
354		return hotkey
355			.replace(/Command/g, "\u2318")
356			.replace(/Control/g, "\u2303")
357			.replace(/Option/g, "\u2325")
358			.replace(/Alt/g, "\u2325")
359			.replace(/Shift/g, "\u21E7");
360	}
361	
362	/**
363	 * Check if a hotkey is valid for hands-free (press) mode.
364	 * Returns null if valid, error message string if invalid.
365	 */
366	export function validateHandsFreeHotkey(hotkey: string): string | null {
367		if (isValidHotkey(hotkey)) return null;
368		return "Use modifier keys plus one regular key.";
369	}
370	
371	/**
372	 * Check if a hotkey is valid for hold-to-speak mode.
373	 * FN alone is not allowed as it conflicts with system functionality.
374	 * Returns null if valid, error message string if invalid.
375	 */
376	export function validateHoldToSpeakHotkey(hotkey: string): string | null {
377		if (hotkey === "Fn") {
378			return "FN cannot be used as hold-to-speak hotkey";
379		}
380		return validateHandsFreeHotkey(hotkey);
381	}
