async function registerSystemHotkey(
    hotkey: string,
    handlers: HotkeyHandlers
): Promise<RegisteredHotkey> {
    const expectedKeys = systemKeysFromHotkey(hotkey);
    const watcherStarted = await startSystemKeyWatcher();  // Calls Rust command

    // Listen for system-key-pressed events from Rust
    const unlistenPressed = await listen<SystemKeyPressedPayload>(
        "system-key-pressed", 
        (event) => {
            if (!systemKeySetsMatch(event.payload.pressedKeys, expectedKeys)) return;
            if (isHeld) return;
            if (isRecorderActive) return;
            isHeld = true;
            handlers.onPressed();  // Call handler
        }
    );

    // Listen for release events
    const unlistenReleased = await listen("system-keys-released", () => {
        if (isHeld) handlers.onReleased?.();
        isHeld = false;
    });

    return { hotkey, dispose: async () => { /* cleanup */ } };
}
```

